// Helper function to add pass to render graph
void AddPass_K5Resources(
    FRDGBuilder& GraphBuilder,
    float seed,
    FRDGTextureRef OutputTexture,
    FIntVector GroupCount
)
{
    FK5ResourcesShader::FParameters* Params = GraphBuilder.AllocParameters<FK5ResourcesShader::FParameters>();
    // Bind Scalars
    Params->seed = seed;
    // Bind UAVs
    Params->OutputTexture = GraphBuilder.CreateUAV(OutputTexture);

    FK5ResourcesShader::Exec(GraphBuilder, *Params, GroupCount);
}
